/**
 * The banner on every generated module. It says three things, because a generated file that does
 * not say it is generated is a file someone edits once and loses.
 */
export const GENERATED_HEADER = `// Copyright Ayers Electronics Inc. All rights reserved.
// SPDX-License-Identifier: Apache-2.0
//
// GENERATED by assemblejs build. Do not edit, and do not commit.
//
// The build writes this from the project's directories (src/assemblies, src/pages, src/api) on
// every build and every dev start, so the built server and the browser have a static import
// graph and nothing scans a directory at run time.
`;
